-- Shared with dist/js/account-location.js; generated by build-account-location.mjs.
begin;
create or replace function salah_counter_private.canonical_location(p_city text,p_country text)
returns table(city text,country text) language plpgsql immutable security invoker set search_path=pg_catalog as $location$
declare nations constant jsonb := '{"россия":"Россия","ru":"Россия","russia":"Россия","российская федерация":"Россия","азербайджан":"Азербайджан","az":"Азербайджан","azerbaijan":"Азербайджан","таджикистан":"Таджикистан","tj":"Таджикистан","tajikistan":"Таджикистан","узбекистан":"Узбекистан","uz":"Узбекистан","uzbekistan":"Узбекистан","казахстан":"Казахстан","kz":"Казахстан","kazakhstan":"Казахстан","кыргызстан":"Кыргызстан","киргизия":"Кыргызстан","kg":"Кыргызстан","kyrgyzstan":"Кыргызстан","саудовская аравия":"Саудовская Аравия","sa":"Саудовская Аравия","saudi arabia":"Саудовская Аравия","оаэ":"ОАЭ","ae":"ОАЭ","united arab emirates":"ОАЭ"}'::jsonb;
 towns constant jsonb := '{"тюмень":["Тюмень","Россия"],"tyumen":["Тюмень","Россия"],"омск":["Омск","Россия"],"omsk":["Омск","Россия"],"буйнакск":["Буйнакск","Россия"],"buynaksk":["Буйнакск","Россия"],"гянджа":["Гянджа","Азербайджан"],"ganja":["Гянджа","Азербайджан"],"москва":["Москва","Россия"],"санкт-петербург":["Санкт-Петербург","Россия"],"казань":["Казань","Россия"],"екатеринбург":["Екатеринбург","Россия"],"уфа":["Уфа","Россия"],"тюкалинск":["Тюкалинск","Россия"],"тюльган":["Тюльган","Россия"],"медина":["Медина","Саудовская Аравия"],"мекка":["Мекка","Саудовская Аравия"],"душанбе":["Душанбе","Таджикистан"],"худжанд":["Худжанд","Таджикистан"],"ташкент":["Ташкент","Узбекистан"],"алматы":["Алматы","Казахстан"],"дубай":["Дубай","ОАЭ"],"тюп":["Тюп","Кыргызстан"]}'::jsonb;
 name text := left(regexp_replace(btrim(coalesce(p_city,'')),'\s+',' ','g'),160);
 nation text := left(regexp_replace(btrim(coalesce(p_country,'')),'\s+',' ','g'),160);
 suffix text[]; ending text; known jsonb;
begin
 if name='' then return query select null::text,null::text;return;end if;
 nation:=coalesce(nations->>replace(lower(nation),'ё','е'),nation);
 suffix:=regexp_match(name,'^(.*),\s*([^,]+)$');
 if suffix is not null then ending:=nations->>replace(lower(btrim(suffix[2])),'ё','е');end if;
 if ending is not null and (nation='' or nation=ending) then name:=btrim(suffix[1]);nation:=ending;end if;
 known:=towns->replace(lower(name),'ё','е');
 if known is not null then name:=known->>0;if nation='' then nation:=known->>1;end if;end if;
 return query select nullif(name,''),nullif(nation,'');
end;$location$;
revoke all on function salah_counter_private.canonical_location(text,text) from public,anon,authenticated;
grant execute on function salah_counter_private.canonical_location(text,text) to service_role;
with resolved as(select c.user_id,n.city,n.country from salah_counter_private.account_context c cross join lateral salah_counter_private.canonical_location(c.city,c.country)n)
update salah_counter_private.account_context c set city=r.city,country=r.country from resolved r where r.user_id=c.user_id and (c.city is distinct from r.city or c.country is distinct from r.country);
commit;
